head.script:
scwin.onpageload = function () {
    scwin.setReturnValue("셀 표시값 : " + scwin.getCellText(0, "calHour") + " (기대 : 2026-10-01 09)");
};

// 화면에 표시된 셀 텍스트
scwin.getCellText = function (rowIndex, colId) {
    let td = grd_data.render.querySelectorAll("td[data-col_id='" + colId + "']")[rowIndex];
    return td ? td.textContent : "";
};

// yyyyMMddHH 값을 yyyy-MM-dd HH 형식으로 변환 (기대 표시값)
scwin.toDisplay = function (value) {
    value = String(value);
    return value.substr(0, 4) + "-" + value.substr(4, 2) + "-" + value.substr(6, 2) + " " + value.substr(8, 2);
};

// 팝업 달력으로 셀 값이 바뀌면 표시값 / 저장 데이터 출력
scwin.dlt_data_oncelldatachange = function (info) {
    setTimeout(function () {
        let data = grd_data.getCellData(info.rowIndex, info.colID);
        scwin.setReturnValue("[편집] 셀 표시값 : " + scwin.getCellText(info.rowIndex, info.colID) + " (기대 : " + scwin.toDisplay(data) + ")"
            + " / getCellData : " + data + " (기대 : yyyyMMddHH 10자리)");
    }, 0);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
